    lastHeartbeat = millis();
    doorCandidate = doorOpen();
    doorCandidateSince = millis();
}

void loop()
{
    serviceDoor();
    serviceSiren();

    unsigned long now = millis();
    if (now - lastHeartbeat >= HEARTBEAT_MS)
    {
        lastHeartbeat = now;
        emitHeartbeat();
    }
}

// Bench chemistry pH logger for the teaching lab.
// Linearized probe on A1 (500 mV/pH), range LED on D10.

const int PH_PIN = A1;
const int RANGE_PIN = 10;
const float MV_PER_PH = 500.0f;
const float LOW_PH = 6.50f;
const float HIGH_PH = 8.50f;
const float HYST_PH = 0.05f;
const unsigned long PERIOD_MS = 1000;
const unsigned long CONFIRM_MS = 300;

unsigned long lastPrint = 0;
unsigned long sampleCount = 0;
float phValue = 0.0f;
float phMin = 14.0f;
float phMax = 0.0f;
bool inBand = true;
bool pendingInBand = true;
unsigned long pendingSince = 0;

float adcMillivolts(int raw)
{
    return raw * (5000.0f / 1023.0f);
}

float millivoltsToPh(float mv)
{
    return mv / MV_PER_PH;
}

void trackPh(float ph)
{
    if (ph < phMin)
    {
        phMin = ph;
    }
    if (ph > phMax)
    {
        phMax = ph;
    }
}

void updateRangeLamp(float ph)
{
    bool wantInBand;
    if (inBand)
    {
        wantInBand = !(ph < LOW_PH - HYST_PH || ph > HIGH_PH + HYST_PH);
    }
    else
    {
        wantInBand = (ph >= LOW_PH + HYST_PH && ph <= HIGH_PH - HYST_PH);
    }

    unsigned long now = millis();
    if (wantInBand != pendingInBand)
    {
        pendingInBand = wantInBand;
        pendingSince = now;
    }
    else if (wantInBand != inBand && (now - pendingSince) >= CONFIRM_MS)
    {
        inBand = wantInBand;
    }

    digitalWrite(RANGE_PIN, inBand ? LOW : HIGH);
}

void printPh()
{
    Serial.print("pH: ");
    Serial.println(phValue, 2);
}

void setup()
{
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
    pendingSince = millis();
}

void loop()
{
    int raw = analogRead(PH_PIN);
    float mv = adcMillivolts(raw);
    phValue = millivoltsToPh(mv);
    sampleCount++;
    trackPh(phValue);
    updateRangeLamp(phValue);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printPh();
    }
}

// Compact laundry fill/run cycle controller.
// Level probe on A0 (10 mV/cm), fill valve on D9, drum motor on D10.
// Reset button on D4 (pull-up) returns to IDLE.

const int LEVEL_PIN = A0;
const int VALVE_PIN = 9;
const int MOTOR_PIN = 10;
const int RESET_PIN = 4;
const float EMPTY_CM = 10.0f;
const float FULL_CM = 25.0f;
const float RUN_MIN_CM = 20.0f;
const float MV_PER_CM = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

enum CycleState
{
    ST_IDLE = 0,
    ST_FILL = 1,
    ST_RUN = 2
};

CycleState state = ST_IDLE;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float levelCm = 0.0f;

float readLevelCm()
{
    int raw = analogRead(LEVEL_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void driveOutputs()
{
    digitalWrite(VALVE_PIN, state == ST_FILL ? HIGH : LOW);
    digitalWrite(MOTOR_PIN, levelCm >= RUN_MIN_CM ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("laundry st=");
    Serial.print((int)state);
    Serial.print(" cm=");
    Serial.println(levelCm, 1);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(MOTOR_PIN, OUTPUT);
    pinMode(RESET_PIN, INPUT_PULLUP);
    driveOutputs();
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        levelCm = readLevelCm();

        if (digitalRead(RESET_PIN) == LOW)
        {
            state = ST_IDLE;
        }
        else if (state == ST_IDLE && levelCm < EMPTY_CM)
        {
            state = ST_FILL;
        }
        else if (state == ST_FILL)
        {
            if (levelCm >= FULL_CM)
            {
                state = ST_RUN;
            }
        }
        else if (state == ST_RUN)
        {
            if (levelCm < RUN_MIN_CM)
            {
                state = ST_IDLE;
            }
        }

        driveOutputs();
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long CONFIRM_MS = 300;
const unsigned long BOOST_DEBOUNCE_MS = 100;

bool fanOn = false;
bool onActive = false;
bool offActive = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
bool boostStable = false;
bool boostLast = false;
unsigned long boostSince = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
    boostSince = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool boostRaw = (digitalRead(BOOST_PIN) == LOW);
        if (boostRaw != boostLast)
        {
            boostLast = boostRaw;
            boostSince = now;
        }
        else if (boostRaw != boostStable && (now - boostSince) >= BOOST_DEBOUNCE_MS)
        {
            boostStable = boostRaw;
        }

        if (boostStable)
        {
            onActive = false;
            offActive = false;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C)
            {
                if (!onActive)
                {
                    onActive = true;
                    onSince = now;
                }
            }
            else
            {
                onActive = false;
            }
            if (tempC <= OFF_C)
            {
                if (!offActive)
                {
                    offActive = true;
                    offSince = now;
                }
            }
            else
            {
                offActive = false;
            }

            if (onActive && (now - onSince) >= CONFIRM_MS)
            {
                driveFan(true);
            }
            else if (offActive && (now - offSince) >= CONFIRM_MS)
            {
                driveFan(false);
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

// Greenhouse mist injector timed pulse.
// Trigger on D4 (pull-up), injector on D9, ready lamp on D12.

const int TRIG_PIN = 4;
const int INJ_PIN = 9;
const int READY_PIN = 12;
const unsigned long PULSE_MS = 800;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 450;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long shots = 0;

void injHigh()
{
    digitalWrite(INJ_PIN, HIGH);
}

void injLow()
{
    digitalWrite(INJ_PIN, LOW);
}

void setReady(bool on)
{
    digitalWrite(READY_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("mist shots=");
    Serial.print(shots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(INJ_PIN, OUTPUT);
    pinMode(READY_PIN, OUTPUT);
    injLow();
    setReady(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            shots++;
            injHigh();
            setReady(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        injLow();
        setReady(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Harbor nav beacon: 500 ms on / 500 ms off on D12.
// Quiet mode switch on D3 (pull-up). Status over UART.

const int BEACON_PIN = 12;
const int QUIET_PIN = 3;
const byte HALF_MS = 500;
const unsigned long STATUS_MS = 2000;
const unsigned long QUIET_DEBOUNCE_MS = 20;

bool lampOn = false;
unsigned long phaseMs = 0;
unsigned long lastLoop = 0;
unsigned long lastStatus = 0;
unsigned long risingCount = 0;
bool quietHeld = false;
bool quietRaw = false;
unsigned long quietChangeMs = 0;

void setBeacon(bool on)
{
    lampOn = on;
    digitalWrite(BEACON_PIN, on ? HIGH : LOW);
}

void emitTick()
{
    Serial.println("tick");
    risingCount++;
}

void publishStatus()
{
    Serial.print("nav rises=");
    Serial.print(risingCount);
    Serial.print(" quiet=");
    Serial.println(quietHeld ? 1 : 0);
}

bool readQuiet()
{
    return digitalRead(QUIET_PIN) == LOW;
}

void setup()
{
    pinMode(BEACON_PIN, OUTPUT);
    pinMode(QUIET_PIN, INPUT_PULLUP);
    setBeacon(false);
    Serial.begin(9600);
    lastLoop = millis();
    lastStatus = millis();
    quietRaw = readQuiet();
    quietHeld = quietRaw;
    quietChangeMs = lastLoop;
}

void loop()
{
    unsigned long now = millis();
    unsigned long elapsed = now - lastLoop;
    lastLoop = now;

    bool raw = readQuiet();
    if (raw != quietRaw)
    {
        quietRaw = raw;
        quietChangeMs = now;
    }
    if (quietRaw != quietHeld && (now - quietChangeMs) >= QUIET_DEBOUNCE_MS)
    {
        quietHeld = quietRaw;
    }

    if (quietHeld)
    {
        setBeacon(false);
        phaseMs = 0;
    }
    else
    {
        phaseMs += elapsed;
        while (phaseMs >= HALF_MS)
        {
            phaseMs -= HALF_MS;
            bool nextOn = !lampOn;
            setBeacon(nextOn);
            if (nextOn)
            {
                emitTick();
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Control-panel key: toggles a status LED for the technician.
// Key on D2 (pull-up to Vcc, closes to ground), LED on D13.

const int KEY_PIN = 2;
const int LED_PIN = 13;
const unsigned long REPORT_MS = 1000;
const unsigned long SETTLE_MS = 40;

bool ledLit = false;
int previous = HIGH;
unsigned long lastReport = 0;
unsigned long edgeCount = 0;
unsigned long bootMs = 0;

int stableLevel = HIGH;
int lastRaw = HIGH;
unsigned long rawChangeMs = 0;

void writeLed(bool on)
{
    ledLit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void flipLed()
{
    writeLed(!ledLit);
    edgeCount++;
}

bool fallingEdge(int previousLevel, int currentLevel)
{
    return previousLevel == HIGH && currentLevel == LOW;
}

void report()
{
    Serial.print("panel led=");
    Serial.print(ledLit ? 1 : 0);
    Serial.print(" edges=");
    Serial.println(edgeCount);
}

void setup()
{
    pinMode(KEY_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    writeLed(false);
    Serial.begin(9600);
    previous = digitalRead(KEY_PIN);
    lastReport = millis();
    bootMs = millis();

    lastRaw = previous;
    stableLevel = previous;
    rawChangeMs = millis();
}

void loop()
{
    int nowLevel = digitalRead(KEY_PIN);
    unsigned long t = millis();

    if (nowLevel != lastRaw)
    {
        lastRaw = nowLevel;
        rawChangeMs = t;
    }

    if (t - rawChangeMs >= SETTLE_MS && lastRaw != stableLevel)
    {
        stableLevel = lastRaw;
        if (fallingEdge(previous, stableLevel))
        {
            flipLed();
        }
        previous = stableLevel;
    }

    if (t - lastReport >= REPORT_MS)
    {
        lastReport = t;
        report();
    }
}

// Front porch gate chime.
// Gate contact on D3 (pull-up, active LOW when open), chime coil on D10.
// Keep a UART heartbeat alive for the monitoring hub.

const uint8_t GATE_PIN = 3;
const uint8_t CHIME_PIN = 10;
const unsigned long CHIME_MS = 1800;
const unsigned long HB_MS = 300;
const unsigned long DEBOUNCE_MS = 30;

unsigned long lastHb = 0;
unsigned long openCount = 0;

bool chimeActive = false;
unsigned long chimeStart = 0;

bool rawOpen = false;
unsigned long rawSince = 0;
bool gateOpen = false;

void chimeHigh()
{
    digitalWrite(CHIME_PIN, HIGH);
}

void chimeLow()
{
    digitalWrite(CHIME_PIN, LOW);
}

void startChime(unsigned long now)
{
    openCount++;
    chimeActive = true;
    chimeStart = now;
    chimeHigh();
}

void serviceChime(unsigned long now)
{
    if (chimeActive && (now - chimeStart >= CHIME_MS))
    {
        chimeActive = false;
        chimeLow();
    }
}

void sendHb()
{
    Serial.println("gate-hb");
}

bool gateOpened()
{
    return digitalRead(GATE_PIN) == LOW;
}

void updateGate(unsigned long now)
{
    bool raw = gateOpened();
    if (raw != rawOpen)
    {
        rawOpen = raw;
        rawSince = now;
    }
    if ((now - rawSince >= DEBOUNCE_MS) && (raw != gateOpen))
    {
        gateOpen = raw;
    }
}

void setup()
{
    pinMode(GATE_PIN, INPUT_PULLUP);
    pinMode(CHIME_PIN, OUTPUT);
    chimeLow();
    Serial.begin(9600);
    lastHb = millis();
    rawOpen = gateOpened();
    rawSince = lastHb;
    gateOpen = rawOpen;
}

void loop()
{
    unsigned long now = millis();

    updateGate(now);

    if (gateOpen && !chimeActive)
    {
        startChime(now);
    }

    serviceChime(now);

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        sendHb();
    }
}

// Process-skid flow monitor with low-flow alarm lamp.
// Flow transducer on A0 (2 mV per L/h), alarm lamp on D8.

const int FLOW_PIN = A0;
const int ALARM_PIN = 8;
const float LOW_FLOW_LPH = 100.0f;
const float HIGH_FLOW_LPH = 800.0f;
const unsigned long LOG_MS = 500;
const unsigned long CONFIRM_MS = 400;

bool alarmLit = false;
bool pendingAlarm = false;
unsigned long pendingSince = 0;
unsigned long lastLog = 0;
unsigned long sampleCount = 0;
float flowLph = 0.0f;
float peakLph = 0.0f;

float readFlowLph()
{
    int raw = analogRead(FLOW_PIN);
    float mv = (float)raw * 5000.0f / 1023.0f;
    return mv / 2.0f;
}

void setAlarm(bool on)
{
    alarmLit = on;
    digitalWrite(ALARM_PIN, on ? HIGH : LOW);
}

bool flowLooksLow(float flow)
{
    return flow < LOW_FLOW_LPH;
}

void notePeak(float flow)
{
    if (flow > peakLph)
    {
        peakLph = flow;
    }
}

void emitLog()
{
    Serial.print("flow: ");
    Serial.println(flowLph, 1);
}

void setup()
{
    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);
    Serial.begin(9600);
    lastLog = millis();
    peakLph = 0.0f;
    pendingAlarm = false;
    pendingSince = millis();
}

void loop()
{
    flowLph = readFlowLph();
    sampleCount++;
    notePeak(flowLph);

    bool wantAlarm = flowLooksLow(flowLph);
    unsigned long now = millis();
    if (wantAlarm != pendingAlarm)
    {
        pendingAlarm = wantAlarm;
        pendingSince = now;
    }
    else if (wantAlarm != alarmLit && (now - pendingSince) >= CONFIRM_MS)
    {
        setAlarm(wantAlarm);
    }

    if ((now - lastLog) >= LOG_MS)
    {
        lastLog = now;
        emitLog();
    }
}

// Linear rail carriage motor enable with end-stop.
// Limit switch on D2 (pull-up to GND when hit), motor enable on D13.
// Jog button on D4 (pull-up) requests motion when clear.

const int LIMIT_PIN = 2;
const int MOTOR_PIN = 13;
const int JOG_PIN = 4;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long STATUS_MS = 900;

int stableLimit = HIGH;
int lastLimit = HIGH;
unsigned long limitEdge = 0;
bool motorEnabled = false;
unsigned long lastStatus = 0;
unsigned long hitCount = 0;

bool limitActiveRaw()
{
    return digitalRead(LIMIT_PIN) == LOW;
}

void setMotor(bool enabled)
{
    motorEnabled = enabled;
    digitalWrite(MOTOR_PIN, enabled ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("rail motor=");
    Serial.print(motorEnabled ? 1 : 0);
    Serial.print(" hits=");
    Serial.println(hitCount);
}

void setup()
{
    pinMode(LIMIT_PIN, INPUT_PULLUP);
    pinMode(JOG_PIN, INPUT_PULLUP);
    pinMode(MOTOR_PIN, OUTPUT);
    setMotor(true);
    Serial.begin(9600);
    stableLimit = digitalRead(LIMIT_PIN);
    lastLimit = stableLimit;
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(LIMIT_PIN);

    if (raw != lastLimit)
    {
        limitEdge = now;
        lastLimit = raw;
    }

    if ((now - limitEdge) >= DEBOUNCE_MS && raw != stableLimit)
    {
        stableLimit = raw;
        if (limitActiveRaw())
        {
            hitCount++;
        }
    }

    bool hit = (stableLimit == LOW);
    bool jog = (digitalRead(JOG_PIN) == LOW);

    if (hit)
    {
        setMotor(false);
    }
    else if (jog)
    {
        setMotor(true);
    }
    else
    {
        setMotor(true);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Shop bench run/stop: mushroom estop toggles the "machine armed" lamp.
// Estop contact on D6 (NC to ground via switch, pull-up), armed lamp on D9.

const uint8_t ESTOP_PIN = 6;
const uint8_t ARMED_PIN = 9;
const unsigned long BEAT_MS = 1200;
const unsigned long SETTLE_MS = 50;

bool armed = false;
uint8_t stableSample = HIGH;
uint8_t priorSample = HIGH;
unsigned long lastChangeMs = 0;
unsigned long lastBeat = 0;
unsigned long pressCount = 0;
unsigned long bootMs = 0;

void writeArmed(bool level)
{
    armed = level;
    digitalWrite(ARMED_PIN, level ? HIGH : LOW);
}

void toggleArmed()
{
    writeArmed(!armed);
    pressCount++;
}

bool fallingEdge(uint8_t previous, uint8_t current)
{
    return previous == HIGH && current == LOW;
}

void heartbeat()
{
    Serial.print("shop armed=");
    Serial.print(armed ? 1 : 0);
    Serial.print(" presses=");
    Serial.println(pressCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(ARMED_PIN, OUTPUT);
    writeArmed(false);
    Serial.begin(9600);
    stableSample = digitalRead(ESTOP_PIN);
    priorSample = stableSample;
    lastChangeMs = millis();
    lastBeat = millis();
    bootMs = millis();
}

void loop()
{
    uint8_t sample = digitalRead(ESTOP_PIN);
    unsigned long now = millis();

    if (sample != stableSample)
    {
        stableSample = sample;
        lastChangeMs = now;
    }
    else if (now - lastChangeMs >= SETTLE_MS)
    {
        if (fallingEdge(priorSample, stableSample))
        {
            toggleArmed();
        }
        priorSample = stableSample;
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

// CNC spindle tach display.
// Tach voltage on A5 (1 mV/rpm), warn lamp on D9, mute on D3.

const int TACH_PIN = A5;
const int WARN_PIN = 9;
const int MUTE_PIN = 3;
const float WARN_RPM = 2000.0f;
const unsigned long PERIOD_MS = 1000;
const unsigned long SAMPLE_MS = 50;

unsigned long lastPrint = 0;
unsigned long lastSample = 0;
float rpm = 0.0f;
float rpmMin = 99999.0f;
float rpmMax = 0.0f;
bool warnLit = false;

float readRpm()
{
    int raw = analogRead(TACH_PIN);
    return raw * (5000.0f / 1023.0f);
}

void trackExtremes(float v)
{
    if (v < rpmMin)
    {
        rpmMin = v;
    }
    if (v > rpmMax)
    {
        rpmMax = v;
    }
}

void updateWarn(float v)
{
    bool muted = (digitalRead(MUTE_PIN) == LOW);
    warnLit = (!muted) && (v >= WARN_RPM);
    digitalWrite(WARN_PIN, warnLit ? HIGH : LOW);
}

void printRpm(float v)
{
    Serial.print("RPM:");
    Serial.println(v, 0);
}

void setup()
{
    pinMode(WARN_PIN, OUTPUT);
    pinMode(MUTE_PIN, INPUT_PULLUP);
    digitalWrite(WARN_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
    lastSample = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        rpm = readRpm();
        trackExtremes(rpm);
        updateWarn(rpm);
    }

    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printRpm(rpm);
        Serial.print("spindle min=");
        Serial.print(rpmMin, 0);
        Serial.print(" max=");
        Serial.println(rpmMax, 0);
    }
}

// Walk-in cooler compressor controller.
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float FAULT_LOW_C = 0.0f;
const float FAULT_HIGH_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const int HOLD_N = 3;

bool cooling = false;
int onHold = 0;
int offHold = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (service || fault)
        {
            onHold = 0;
            offHold = 0;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                onHold++;
            }
            else
            {
                onHold = 0;
            }

            if (tempC <= COOL_OFF_C)
            {
                offHold++;
            }
            else
            {
                offHold = 0;
            }

            if (onHold >= HOLD_N)
            {
                setCompressor(true);
            }
            else if (offHold >= HOLD_N)
            {
                setCompressor(false);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Patio weather node: TMP36 logger with hold-to-freeze button.
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float MV_PER_C = 10.0f;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const float HYST_C = 1.0f;
const unsigned long PERIOD_MS = 1000;
const unsigned long DEBOUNCE_MS = 20;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
bool freezeRaw = false;
bool lampOn = false;
unsigned long lastFreezeChange = 0;
unsigned long samples = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1023.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    if (lampOn)
    {
        if ((c >= LOW_C + HYST_C) && (c <= HIGH_C - HYST_C))
        {
            lampOn = false;
        }
    }
    else
    {
        if ((c < LOW_C) || (c > HIGH_C))
        {
            lampOn = true;
        }
    }
    digitalWrite(RANGE_PIN, lampOn ? HIGH : LOW);
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    samples++;

    bool raw = (digitalRead(FREEZE_PIN) == LOW);
    unsigned long now = millis();
    if (raw != freezeRaw)
    {
        freezeRaw = raw;
        lastFreezeChange = now;
    }
    if ((now - lastFreezeChange) >= DEBOUNCE_MS && freezeHeld != freezeRaw)
    {
        freezeHeld = freezeRaw;
        if (freezeHeld)
        {
            frozenC = tempC;
        }
    }

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(report);

    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

// Patio weather node: TMP36 logger (known-good build).
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const float HYST_C = 1.0f;
const unsigned long CONFIRM_MS = 100;
const unsigned long PERIOD_MS = 1000;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
unsigned long samples = 0;

bool lampOn = false;
bool pendingLamp = false;
unsigned long pendingSince = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1023.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    bool want;
    if (lampOn)
    {
        want = (c < (LOW_C - HYST_C)) || (c > (HIGH_C + HYST_C));
    }
    else
    {
        want = (c < (LOW_C + HYST_C)) || (c > (HIGH_C - HYST_C));
    }

    unsigned long now = millis();
    if (want != lampOn)
    {
        if (want != pendingLamp)
        {
            pendingLamp = want;
            pendingSince = now;
        }
        else if (now - pendingSince >= CONFIRM_MS)
        {
            lampOn = want;
            digitalWrite(RANGE_PIN, lampOn ? HIGH : LOW);
        }
    }
    else
    {
        pendingLamp = lampOn;
        pendingSince = now;
    }
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    samples++;
    freezeHeld = (digitalRead(FREEZE_PIN) == LOW);
    if (freezeHeld)
    {
        frozenC = tempC;
    }

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(report);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

// Compressed-air manifold pressure logger for the workshop.
// Transducer on A2: 10 mV/kPa with 500 mV zero offset. Gauge lamp on D12.

const int PRESSURE_PIN = A2;
const int GAUGE_PIN = 12;
const float WARN_KPA = 90.0f;
const float MV_PER_KPA = 10.0f;
const float MV_OFFSET = 500.0f;
const unsigned long SAMPLE_MS = 1000;
const unsigned long GAUGE_POLL_MS = 10;
const unsigned long GAUGE_CONFIRM_MS = 100;

unsigned long lastSample = 0;
unsigned long readingCount = 0;
float lastKpa = 0.0f;
float minKpa = 9999.0f;
float maxKpa = 0.0f;
bool gaugeLit = false;

unsigned long lastGaugePoll = 0;
bool pendingLit = false;
unsigned long pendingSince = 0;

float readMillivolts()
{
    int raw = analogRead(PRESSURE_PIN);
    return raw * (5000.0f / 1023.0f);
}

float millivoltsToKpa(float mv)
{
    return (mv - MV_OFFSET) / MV_PER_KPA;
}

void trackExtremes(float kpa)
{
    if (kpa < minKpa)
    {
        minKpa = kpa;
    }
    if (kpa > maxKpa)
    {
        maxKpa = kpa;
    }
}

void updateGauge(float kpa)
{
    gaugeLit = (kpa >= WARN_KPA);
    digitalWrite(GAUGE_PIN, gaugeLit ? HIGH : LOW);
}

void pollGauge()
{
    unsigned long now = millis();
    if (now - lastGaugePoll < GAUGE_POLL_MS)
    {
        return;
    }
    lastGaugePoll = now;

    float kpa = millivoltsToKpa(readMillivolts());
    bool wantLit = (kpa >= WARN_KPA);

    if (wantLit == gaugeLit)
    {
        pendingLit = wantLit;
        pendingSince = now;
        return;
    }

    if (wantLit != pendingLit)
    {
        pendingLit = wantLit;
        pendingSince = now;
        return;
    }

    if (now - pendingSince >= GAUGE_CONFIRM_MS)
    {
        updateGauge(kpa);
        pendingLit = wantLit;
        pendingSince = now;
    }
}

void printReading()
{
    Serial.print("kPa: ");
    Serial.println(lastKpa, 1);
}

void setup()
{
    pinMode(GAUGE_PIN, OUTPUT);
    digitalWrite(GAUGE_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastGaugePoll = millis();
    pendingLit = false;
    pendingSince = millis();
}

void loop()
{
    pollGauge();

    unsigned long now = millis();
    if (now - lastSample < SAMPLE_MS)
    {
        return;
    }
    lastSample = now;

    float mv = readMillivolts();
    lastKpa = millivoltsToKpa(mv);
    readingCount++;
    trackExtremes(lastKpa);
    printReading();
}

// Yard path lamp dusk relay.
// Light sensor on A0 (mV as lux-ish units), relay on D8, manual on D3.

const int LIGHT_PIN = A0;
const int RELAY_PIN = 8;
const int MANUAL_PIN = 3;
const float ON_UNITS = 400.0f;
const float OFF_UNITS = 600.0f;
const unsigned long SAMPLE_MS = 40;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool relayOn = false;
unsigned long lastSample = 0;
unsigned long lastStatus = 0;
float lightU = 0.0f;
bool manualOn = false;
bool pendingManual = false;
unsigned long pendingSince = 0;

float readLightUnits()
{
    int raw = analogRead(LIGHT_PIN);
    return raw * (5000.0f / 1023.0f);
}

void setRelay(bool on)
{
    relayOn = on;
    digitalWrite(RELAY_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("yard u=");
    Serial.print(lightU, 0);
    Serial.print(" relay=");
    Serial.println(relayOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(RELAY_PIN, OUTPUT);
    pinMode(MANUAL_PIN, INPUT_PULLUP);
    setRelay(false);
    Serial.begin(9600);
    lastSample = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        lightU = readLightUnits();
        bool manual = (digitalRead(MANUAL_PIN) == LOW);

        if (manual != pendingManual)
        {
            pendingManual = manual;
            pendingSince = now;
        }
        else if (manual != manualOn && now - pendingSince >= CONFIRM_MS)
        {
            manualOn = manual;
        }

        if (manualOn)
        {
            setRelay(true);
        }
        else
        {
            bool wantOn = relayOn;
            if (lightU < ON_UNITS)
            {
                wantOn = true;
            }
            else if (lightU > OFF_UNITS)
            {
                wantOn = false;
            }

            if (wantOn != relayOn)
            {
                setRelay(wantOn);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}
